    "id": 1,
    "slug": "customer-care-service-advisor-excellence",
    "title": "Customer Care & Service Advisor Excellence",
    "description": "Front-desk operations, service-advisor communication, and customer-care standards.",
    "category": "Customer-Facing",
    "level": "Beginner",
    "format": "Workshop",
    "durationHours": 8,
    "priceNaira": 80000,
